WITH laos AS (
  SELECT ST_Union_Agg(ST_Transform(geometry, 'EPSG:4326', 'EPSG:32648', always_xy := true)) AS geom
  FROM countries
  WHERE iso_a3 = 'LAO'
),
disc AS (
  SELECT ST_Buffer(ST_Centroid(geom), 200000) AS geom FROM laos
)
SELECT ROUND(100.0 * ST_Area(ST_Intersection(laos.geom, disc.geom)) / ST_Area(disc.geom), 1) AS pct_covered
FROM laos, disc;
